/* eslint-disable @stencil-community/ban-default-true, @stencil-community/required-jsdoc */
import {
  Component,
  Element,
  EventEmitter,
  h,
  Prop,
  Event,
  Host,
  ComponentInterface,
  State,
  Fragment,
  Watch,
} from '@stencil/core';
import { Status } from '@src/shared/base-props';
import { TimezoneInfo } from '@src/shared/timezone';
import { utcOffsetToLabel } from '../utils';
import { Slot, Slots } from '@src/framework/decorators';
import { Dayjs } from 'dayjs';
import {
  NormalizedDatePickerComparisonProps,
  DatePickerViewMode,
  DatePresetOptions,
  ValueChangeInfo,
  ComparisonChangeInfo,
  DatePresetShortcutStrict,
  DateComparisonPresetShortcut,
  DateTimeFormatOptions,
} from '../types';
import { Placement } from '@floating-ui/dom';
import { t } from '@src/shared/i18n';
import { commonMessages } from '@fe-infra/keystone-locales';

const prefix = 'picker-core';

/**
 * The DateTimePickerBase component serves two primary purposes:
 * 1. Normalization: It normalizes external prop values into a consistent internal format for use by internal components.
 * 2. Composition: It assembles and orchestrates the various internal components (e.g., Calendar, TimePanel) that constitute the complete date-time picker.
 */
@Component({
  tag: 'ks-date-time-picker-core',
  styleUrl: 'index.scss',
  shadow: true,
})
export class KsDateTimePickerCore implements ComponentInterface {
  @Element() el!: HTMLKsDateTimePickerCoreElement;

  @Prop() clearable!: boolean;
  @Prop() status!: Status;
  @Prop() timezone!: TimezoneInfo;
  @Prop() showTimezone!: false | { placement: 'input' | 'panel'; style?: 'longOffset' | 'full' };
  @Prop() placement!: Placement;
  @Prop() open!: boolean;
  @Prop() presets!: boolean | { options: DatePresetOptions };
  @Prop() needConfirm!: boolean;
  @Prop() showCancel!: boolean;

  @Prop() viewDate!: Dayjs;
  @Prop() now!: Dayjs;

  @Prop() disabledDate!: (
    date: Dayjs,
    info: { type: 'date' | 'preset'; from?: Dayjs; to?: Dayjs; selectionPhase?: 'start' | 'end' },
  ) => boolean;

  @Event({ bubbles: false, composed: false }) ksClear!: EventEmitter<void>;

  @Slot({ slotname: 'popupExtraFooter' }) private popupExtraFooterSlot?: Slots;
  @Slot({ slotname: 'popupFooterAppend' }) private popupFooterAppendSlot?: Slots;
  @Slot({ slotname: 'prefix' }) private prefixSlot?: Slots;

  @Prop() value!: [Dayjs | null, Dayjs | null];
  @Prop() placeholder!: [string | undefined, string | undefined];
  @Prop() disabled!: [boolean, boolean];

  @Prop() comparison!: NormalizedDatePickerComparisonProps;
  @Prop() setComparison!: (comparison: NormalizedDatePickerComparisonProps, reason: ComparisonChangeInfo) => void;
  @Prop() onComparisonPick!: (comparison: NormalizedDatePickerComparisonProps, reason: ComparisonChangeInfo) => void;

  @Prop() viewMode!: DatePickerViewMode;
  @Prop() availableViewModes!: DatePickerViewMode[];

  @Prop() handleViewChange!: (viewDate: Dayjs, viewMode: DatePickerViewMode) => void;

  @Prop() isRange!: boolean;
  /** Whether to render a single DateGrid, or dual to have a broader view of selection. @note Unrelated to `isRange`, purely controls view. */
  @Prop() displayMode!: 'single' | 'dual';
  @Prop() rangeSelectionMode!: 'direct' | '2-step';

  @Prop() setValue!: (value: [Dayjs | null, Dayjs | null], reason: ValueChangeInfo) => void;
  @Prop() setOpen!: (open: boolean) => void;

  @Prop() displayFormatOptions!: DateTimeFormatOptions;
  @Prop() normalizedFormat!: string;

  /** The selectionPhase is only usable for range selection. It will only be `'start'` when not in range selection. */
  @State() private _selectionPhase: 'start' | 'end' | 'idle' = 'start';
  @State() private isSelectingComparisonValue = false;

  @State() presetPreviewDate: [Dayjs | null, Dayjs | null] | null = null;
  private setPresetPreviewDate = (previewDate: [Dayjs | null, Dayjs | null] | null) => {
    this.presetPreviewDate = previewDate;
  };

  @State() hoverPart: 'start' | 'end' | null = null;

  /**
   * This is for storing the draft in `needConfirm` mode.
   * originals do not require to be reactive.
   */
  @State() draft = {
    value: this.value,
    // eslint-disable-next-line no-autofix/@typescript-eslint/no-unnecessary-condition
    comparison: this.comparison || {},
  };
  private draftChangeInfo = {
    value: { reason: 'pick' } as ValueChangeInfo,
    comparison: { reason: 'toggle' } as ComparisonChangeInfo,
  };
  get shouldUseDraft() {
    return this.open && this.needConfirm;
  }
  get valueWithDraft() {
    return this.shouldUseDraft ? this.draft.value : this.value;
  }
  get comparisonWithDraft() {
    return this.shouldUseDraft ? { ...this.comparison, ...this.draft.comparison } : this.comparison;
  }
  private setValueWithDraft = (value: [Dayjs | null, Dayjs | null], reason: ValueChangeInfo) => {
    if (this.shouldUseDraft) {
      this.draft = { ...this.draft, value };
      this.draftChangeInfo.value = reason;
    } else {
      this.setValue(value, reason);
    }
  };
  private setComparisonWithDraft = (comparison: NormalizedDatePickerComparisonProps, reason: ComparisonChangeInfo) => {
    this.onComparisonPick(comparison, reason);
    if (this.shouldUseDraft) {
      this.draft = { ...this.draft, comparison };
      this.draftChangeInfo.comparison = reason;
    } else {
      this.setComparison(comparison, reason);
    }
  };
  private setValueWithDraftByPreset = (
    value: [Dayjs | null, Dayjs | null],
    preset: { key?: DatePresetShortcutStrict },
  ) => {
    this.setValueWithDraft(value, { reason: 'preset', preset } as ValueChangeInfo);
    this.updateSelectionPhase('applyPreset');
  };
  private setComparisonWithDraftByPreset = (
    comparison: NormalizedDatePickerComparisonProps,
    preset: { key?: DateComparisonPresetShortcut },
  ) => {
    this.setComparisonWithDraft(comparison, { reason: 'preset', preset } as ComparisonChangeInfo);
    this.updateSelectionPhase('applyPreset');
  };
  private setComparisonWithDraftByToggle = (comparison: NormalizedDatePickerComparisonProps) =>
    this.setComparisonWithDraft(comparison, { reason: 'toggle' } as ComparisonChangeInfo);

  @Watch('value')
  valueWatcher() {
    if (this.shouldUseDraft) {
      this.draft = { ...this.draft, value: this.value };
    }
  }
  @Watch('comparison')
  comparisonWatcher(
    newComparison: NormalizedDatePickerComparisonProps,
    oldComparison: NormalizedDatePickerComparisonProps,
  ) {
    if (this.shouldUseDraft) {
      const isComparisonValueChanged =
        newComparison.active !== oldComparison.active ||
        newComparison.value[0]?.valueOf() !== oldComparison.value[0]?.valueOf() ||
        newComparison.value[1]?.valueOf() !== oldComparison.value[1]?.valueOf();
      if (isComparisonValueChanged) {
        this.draft = { ...this.draft, comparison: newComparison };
      }
    }
  }

  @Watch('open')
  openWatcher(open: boolean) {
    if (open) {
      if (this.shouldUseDraft) {
        this.draft = { value: this.value, comparison: this.comparison };
        this.draftChangeInfo = { value: { reason: 'pick' }, comparison: { reason: 'toggle' } };
      }
      this.setIsSelectingComparisonValue(false);
    }
  }

  private handleOpenChange = ({ detail: open }: CustomEvent<boolean>) => {
    this.setOpen(open);
    if (open) {
      this.updateSelectionPhase('open');
    }
  };
  private handleClear = () => {
    this.setValue([null, null], { reason: 'clear' });
    this.setComparison({ ...this.comparison, active: false, value: [null, null] }, { reason: 'clear' });
    Object.assign(this.draft, {
      value: [null, null],
      comparison: { ...this.comparison, active: false, value: [null, null] },
    });
    this.setOpen(false);
    this.ksClear.emit();
  };

  // TODO This correction mechanism is tricky, better migrate it to state machine
  private get selectionPhase() {
    if (this.isRange) {
      if (this.disabled[0] && this.disabled[1]) {
        return 'idle';
      } else if (this._selectionPhase === 'start' && this.disabled[0]) {
        return 'end';
      } else if (this._selectionPhase === 'end' && this.disabled[1]) {
        return 'start';
      }
    } else {
      if (this._selectionPhase === 'end' || (this._selectionPhase === 'start' && this.disabled[0])) {
        return 'idle';
      }
    }

    return this._selectionPhase;
  }
  private updateSelectionPhase(action: 'open' | 'pick' | 'applyPreset') {
    const isInComparisonMode = this.comparison.active && !this.isSelectingComparisonValue;
    const canClosePanelAfterSelection = !this.needConfirm && !isInComparisonMode;

    if (action === 'open') {
      if (this.disabled[0] || !this.isRange) {
        this._selectionPhase = 'end';
      } else {
        this._selectionPhase = 'start';
      }
    } else if (action === 'pick') {
      // TODO implement 2-step rangeSelectionMode
      if (this.rangeSelectionMode === 'direct') {
        if (this.selectionPhase === 'start' || this.selectionPhase === 'idle') {
          if (this.disabled[1] || !this.isRange) {
            this._selectionPhase = 'idle';
            canClosePanelAfterSelection && this.setOpen(false);
          } else {
            this._selectionPhase = 'end';
          }
        } else {
          this._selectionPhase = 'idle';
          canClosePanelAfterSelection && this.setOpen(false);
        }
      }
    } else if (action === 'applyPreset') {
      this._selectionPhase = 'idle';
      canClosePanelAfterSelection && this.setOpen(false);
    }
  }

  private setIsSelectingComparisonValue = (v: boolean) => {
    this.isSelectingComparisonValue = v;
    this.updateSelectionPhase('open');
  };
  private setViewDate = (viewDate: Dayjs) => this.handleViewChange(viewDate, this.viewMode);
  private handleComparisonValueChangeByPick = (comparisonValue: [Dayjs | null, Dayjs | null]) => {
    this.setComparisonWithDraft({ ...this.comparisonWithDraft, value: comparisonValue }, { reason: 'pick' });
    this.updateSelectionPhase('pick');
  };
  private handleValueChangeByPick = (value: [Dayjs | null, Dayjs | null]) => {
    this.setValueWithDraft(value, { reason: 'pick' });
    // TODO detect disabled value and find the closest enabled date
    this.updateSelectionPhase('pick');
  };

  private handleHoverPartChange = (hoverPart: 'start' | 'end' | null) => {
    this.hoverPart = hoverPart;
  };

  private handleConfirm = () => {
    if (this.shouldUseDraft) {
      this.setValue(this.draft.value, this.draftChangeInfo.value);
      this.setComparison(this.draft.comparison, this.draftChangeInfo.comparison);
    }
    this.setOpen(false);
  };
  private handleCancel = () => {
    this.setOpen(false);
  };

  private renderTimezoneIndicator() {
    if (!this.showTimezone || this.showTimezone.placement !== 'panel') {
      return;
    }

    const timezoneLabel = this.timezone.label || '';
    const utcOffset = typeof this.timezone.utcOffset === 'number' ? utcOffsetToLabel(this.timezone.utcOffset) : '';

    let label: string = utcOffset;
    if (typeof this.showTimezone === 'object' && this.showTimezone.style === 'full' && timezoneLabel !== '') {
      label = utcOffset !== '' ? `(${utcOffset}) ${timezoneLabel}` : timezoneLabel;
    }

    const timezoneLabelContainer = (
      <div class={`${prefix}__timezone-container`}>
        <ks-text class={`${prefix}__timezone`} variant="labelSm">
          {label}
        </ks-text>
      </div>
    );

    return this.timezone.helpContent ? (
      <ks-tooltip size="md" placement="bottom">
        {timezoneLabelContainer}
        <ks-text variant="labelSm" slot="content" richTextString={this.timezone.helpContent} />
      </ks-tooltip>
    ) : (
      timezoneLabelContainer
    );
  }
  private renderFooter() {
    const timezoneIndicator = this.renderTimezoneIndicator();
    const showFooterAppend = this.needConfirm || this.showCancel || this.popupFooterAppendSlot;
    const showFooter = timezoneIndicator || showFooterAppend;

    // TODO fix slot watch
    return (
      <Fragment>
        {this.popupExtraFooterSlot && (
          <div class={`${prefix}__popup-extra-footer`}>
            <slot name="popupExtraFooter" slot="popupExtraFooter" />
          </div>
        )}

        {showFooter && (
          <div class={`${prefix}__popup-footer`} part="footer">
            {timezoneIndicator}

            <div class={`${prefix}__popup-footer-append`}>
              {this.popupFooterAppendSlot && <slot name="popupFooterAppend" slot="popupFooterAppend"></slot>}
              {this.showCancel && (
                <ks-button size="sm" onClick={this.handleCancel} data-testid="core-index-xpDLeJ">
                  {t(commonMessages.cancel)}
                </ks-button>
              )}

              {this.needConfirm && (
                <ks-button size="sm" variant="primary" onClick={this.handleConfirm} data-testid="core-index-g1HneZ">
                  {t(commonMessages.confirm)}
                </ks-button>
              )}
            </div>
          </div>
        )}
      </Fragment>
    );
  }
  render() {
    return (
      <Host>
        <ks-popover
          size="auto"
          class={`${prefix}__tooltip`}
          arrow={false}
          trigger="click"
          placement={this.placement}
          popupWidth={{ max: '100vw' }}
          popupHeight={{ max: '100vh' }}
          open={this.disabled[0] && this.disabled[1] ? false : this.open}
          gapOffset={0}
          closeOnClickOutside={{ ignoreEls: [this.el] }}
          onKsOpenChange={this.handleOpenChange}
        >
          <ks-date-time-picker-display-field
            exportparts="fieldTimezone"
            value={this.valueWithDraft}
            isRange={this.isRange}
            placeholder={this.placeholder}
            disabled={this.disabled}
            comparison={this.comparisonWithDraft}
            clearable={this.clearable}
            status={this.status}
            timezone={this.timezone}
            hoverPart={this.comparison?.active ? null : this.hoverPart}
            showTimezone={this.showTimezone}
            open={this.open}
            forceActive={this.open}
            displayFormatOptions={this.displayFormatOptions}
            handleClear={this.handleClear}
            data-testid="base-picker-base-uTX8ji"
          >
            {this.prefixSlot && <slot name="prefix" slot="prefix"></slot>}
          </ks-date-time-picker-display-field>

          <div class={`${prefix}__popup`} slot="content">
            {this.open && (
              <Fragment>
                <ks-date-time-picker-comparison
                  value={this.valueWithDraft}
                  isRange={this.isRange}
                  placeholder={this.placeholder}
                  disabled={this.disabled}
                  comparison={this.comparisonWithDraft}
                  setComparison={this.setComparisonWithDraftByToggle}
                  clearable={this.clearable}
                  status={this.status}
                  timezone={this.timezone}
                  showTimezone={this.showTimezone}
                  hoverPart={this.hoverPart}
                  open={this.open}
                  displayFormatOptions={this.displayFormatOptions}
                  isSelectingComparisonValue={this.isSelectingComparisonValue}
                  setIsSelectingComparisonValue={this.setIsSelectingComparisonValue}
                  setViewDate={this.setViewDate}
                  data-testid="core-index-9v3gzk"
                />

                <div class={`${prefix}__popup-body`}>
                  {this.presets && (
                    <ks-date-time-picker-presets
                      value={this.valueWithDraft}
                      setValue={this.setValueWithDraftByPreset}
                      setComparison={this.setComparisonWithDraftByPreset}
                      comparison={this.comparisonWithDraft}
                      isSelectingComparisonValue={this.isSelectingComparisonValue}
                      now={this.now}
                      availableViewModes={this.availableViewModes}
                      isRange={this.isRange}
                      disabledDate={this.disabledDate}
                      disabled={this.disabled}
                      open={this.open}
                      viewMode={this.viewMode}
                      handleViewChange={this.handleViewChange}
                      timezone={this.timezone}
                      normalizedFormat={this.normalizedFormat}
                      presets={this.presets}
                      setPresetPreviewDate={this.setPresetPreviewDate}
                      data-testid="core-index-oHLrEZ"
                    />
                  )}

                  <ks-date-time-picker-date-grid
                    key={`date-grid-${this.isSelectingComparisonValue}`}
                    value={this.isSelectingComparisonValue ? this.comparisonWithDraft.value : this.valueWithDraft}
                    viewDate={this.viewDate}
                    viewMode={this.viewMode}
                    availableViewModes={this.availableViewModes}
                    now={this.now}
                    displayMode={this.displayMode}
                    selectionPhase={this.selectionPhase}
                    isRange={this.isRange}
                    disabledDate={this.disabledDate}
                    disabled={this.disabled}
                    presetPreviewDate={this.presetPreviewDate}
                    handleValueChange={
                      this.isSelectingComparisonValue
                        ? this.handleComparisonValueChangeByPick
                        : this.handleValueChangeByPick
                    }
                    handleViewChange={this.handleViewChange}
                    handleHoverPartChange={this.handleHoverPartChange}
                    data-testid="base-picker-base-mY2j42"
                  />
                </div>

                {this.renderFooter()}
              </Fragment>
            )}
          </div>
        </ks-popover>
      </Host>
    );
  }
}
